#!/usr/bin/env bash
# E14 RD-12 pilot (pre-registration §12): interleaved passive <-> active reading, T4 SmolLM2-360M C5 s1, 3 rounds x 2M tokens.
# Queued 2026-10-17 by workplace-fd at the author's go-ahead. One job per arm (~1 GPU-h each); report on the CPU lane.
set -euo pipefail
PY=${PY:-/home/bhux/anaconda3/envs/vsa-repro/bin/python}
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name e14-rd12-cycle --priority 54.495996 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.e14_rd12 run --arm cycle --run experiments/e9-retrofit/runs/t4/SmolLM2-360M-full-C5-s1 --items experiments/e11-read-to-learn/items/t4-heldout-smollm2-v1 --output experiments/e14-logic/runs/rd12/cycle --data /home/bhux/data/vsa-llm/e14/rd12/cycle --rounds 3 --tokens 2000000 --limit 160 --max-usd 6   # ~1 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name e14-rd12-single --priority 54.495996 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.e14_rd12 run --arm single --run experiments/e9-retrofit/runs/t4/SmolLM2-360M-full-C5-s1 --items experiments/e11-read-to-learn/items/t4-heldout-smollm2-v1 --output experiments/e14-logic/runs/rd12/single --data /home/bhux/data/vsa-llm/e14/rd12/single --rounds 3 --tokens 2000000 --limit 160 --max-usd 6   # ~1 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name e14-rd12-gold --priority 54.495996 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.e14_rd12 run --arm gold --run experiments/e9-retrofit/runs/t4/SmolLM2-360M-full-C5-s1 --items experiments/e11-read-to-learn/items/t4-heldout-smollm2-v1 --output experiments/e14-logic/runs/rd12/gold --data /home/bhux/data/vsa-llm/e14/rd12/gold --rounds 3 --tokens 2000000 --limit 160 --max-usd 6   # ~1 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name e14-rd12-passive --priority 54.495996 --min-free-gb 10 --no-resume -- $PY -m vsa_embed.experiments.e14_rd12 run --arm passive --run experiments/e9-retrofit/runs/t4/SmolLM2-360M-full-C5-s1 --items experiments/e11-read-to-learn/items/t4-heldout-smollm2-v1 --output experiments/e14-logic/runs/rd12/passive --data /home/bhux/data/vsa-llm/e14/rd12/passive --rounds 3 --tokens 2000000 --limit 160 --max-usd 6   # ~1 GPU-h
PYTHONPATH=src $PY -m vsa_embed.jobqueue add --name e14-rd12-report --priority 54.4959969 --no-resume -- $PY -m vsa_embed.experiments.e14_rd12 report --runs experiments/e14-logic/runs/rd12/cycle experiments/e14-logic/runs/rd12/single experiments/e14-logic/runs/rd12/gold experiments/e14-logic/runs/rd12/passive --output experiments/e14-logic/report/rd12
